import ledger

def group(members, expenses=()):
    return {\"currency\": \"USD\", \"members\": members, \"expenses\": list(expenses)}

def expense(payer=\"ΟΣ\", key=\"trip\"):
    return {\"id\": key, \"payer\": payer, \"amount\": \"1\", \"split\": {\"type\": \"equal\"}}

for label, data in (
    (\"Greek sigma payer alias\", group([\"ΟΣ\", \"Bob\"], [expense(\"οσ\")])),
    (\"Greek sigma member duplicates\", group([\"ΟΣ\", \"οσ\"])),
    (\"Non-string expense ID\", group([\"ΟΣ\", \"Bob\"], [expense(key=42)])),
):
    try:
        print(f\"{label}: {ledger.balances(data)"'!r}")
    except ledger.ValidationError as error:
        print(f"{label}: {error}")
print("Greek identity:", "ΟΣ".casefold() == "οσ".casefold())
